386	// TC workspace layout (carved from tok.workspace; host sizes it):
387	//   [0 .. acts_f)                          : MbActs bf16 region
388	//   [acts_f .. + nCTA*scratch)             : per-CTA tile scratch (f32)
389	//   [.. + nCTA*kPartElems)                 : per-CTA non-GEMM grad partials (f32)
390	//   [.. + nCTA)                            : per-CTA loss slots
391	//   [.. + 1)                               : reduced scalar loss
392	//   [.. + mb_dw_part_floats(G))            : split-K dW partials (G>1 only; the
393	//                                            (gt,kc) 64×N partial tiles P2 reduces)
394	__host__ __device__ __forceinline__ int64_t mb_tc_acts_floats(int T) {
395	    return mbtc::mb_acts_floats(T);
396	}
397	// dW split-K partial floats (0 when G==1 → no extra scratch, the single-CTA path).
398	__host__ __device__ __forceinline__ int64_t mb_tc_dw_part_floats() {
399	    return (mbtc::kMbDwSplitK > 1) ? mbtc::mb_dw_part_floats(mbtc::kMbDwSplitK) : 0;
400	}
401	// STAGED-optimizer cross-CTA reduction scratch (Prodigy d-estimate). Mirrors the
402	// decoder's dec_tc_opt_reduce_floats: the Prodigy P2.6 stage publishes per-CTA (r,s)
403	// slots (2*nCTA) + a reduced-d broadcast slot (1) — an owner-computes tree
404	// (opt_stages_precompute.cuh), NO float atomic. Sized for the LARGEST nCTA (one
405	// CTA/SM = #SMs); tiny (≤ 2*132+1 ≈ 1 KB) and carved UNCONDITIONALLY so the opt-
406	// agnostic cached launcher workspace fits every OptId. Unused by AdamW/Lion/… (their
407	// P3 never touches this region), so adding it leaves those cells byte-identical.
408	__host__ __device__ __forceinline__ int64_t mb_tc_opt_reduce_floats(int nCTA) {
409	    return (int64_t)2 * nCTA + 1;            // [r slots | s slots | reduced d]
410	}
411	// ── LookSAM (STAGED in-kernel SAM 2nd backward) transient scratch — the Mamba twin of
412	//    the decoder's dec_tc_looksam_floats. The SAM step perturbs p in place, runs a
413	//    SECOND fwd+bwd at p', and needs (a) a param BACKUP for the exact restore (eager
414	//    clones p before perturbing; an fp32 add is not bit-reversible, so save — don't
415	//    subtract back) + (b) a SEPARATE g_sam grad buffer so the 2nd backward does NOT
416	//    clobber the first grad `grad` (sam_dir = g_sam − grad reads both). Both are total-
417	//    sized + transient (NOT persistent state — sam_dir itself persists in the `extra`
418	//    state slice, bound by the cell). Carved UNCONDITIONALLY (≈ 2·kMambaTotalElems)
419	//    so the opt-agnostic launcher fits every OptId; unused by every non-LookSAM cell
420	//    (its P2.4 phase is if-constexpr'd out → byte-identical). The ‖g‖ reduction reuses
421	//    the loss workspace (sq_part/ron_bc, as GrokAdamW's P2.5 / the decoder twin do), so
422	//    no extra here. ──
423	__host__ __device__ __forceinline__ int64_t mb_tc_looksam_floats() {
424	    return (int64_t)2 * kMambaTotalElems;    // [sam_backup | sam_grad]
425	}
426	// ── Muon (STAGED grid-cooperative Newton-Schulz) per-matrix scratch — the Mamba twin of
427	//    the decoder's dec_tc_muon_floats / the vit's vit_tc_muon_floats. The NS chain runs ONE
428	//    2D weight at a time over all CTAs; the scratch holds X/A/AX/AAX/orth for the LARGEST 2D
429	//    weight + the per-CTA Frobenius-norm partials + inv_norm. The momentum buffer (muon_buf)
430	//    is NOT here — it PERSISTS across steps as optimizer state, bound to the m slice
431	//    (st.exp_avg). Largest mamba 2D weight: in_proj = 512×128 = 65536 numel; largest rows =
432	//    512 ⇒ A = 512×512 (mbtc::kMbMuonMaxNumel/kMbMuonMaxRows). Carved UNCONDITIONALLY (≈
433	//    4·65536 + 512² + nCTA + 1 floats ≈ 2 MB) so the opt-agnostic cached launcher workspace
434	//    fits every OptId; unused by every non-Muon cell (its P2.7/P3-2D branches are if-
435	//    constexpr'd out → byte-identical). ──
436	__host__ __device__ __forceinline__ int64_t mb_tc_muon_floats(int nCTA) {
437	    // X + AX + AAX + orth (each maxNumel) + A (maxRows²) + nrm_partials(nCTA) + inv_norm(1)
438	    return (int64_t)4 * mbtc::kMbMuonMaxNumel
439	         + (int64_t)mbtc::kMbMuonMaxRows * mbtc::kMbMuonMaxRows
440	         + nCTA + 1;
441	}
442	__host__ __device__ __forceinline__ int64_t mb_tc_workspace_floats(int T, int nCTA) {
443	    return mb_tc_acts_floats(T)
444	         + (int64_t)nCTA * mbtc::mb_tile_scratch_floats()
445	         + (int64_t)nCTA * mbtc::kPartElems
446	         + nCTA + 1
447	         + mb_tc_dw_part_floats()                       // split-K dW partials (G>1)
448	         + mb_tc_opt_reduce_floats(nCTA)                // STAGED-opt (Prodigy) reduce slots
449	         + mb_tc_looksam_floats()                       // STAGED-opt (LookSAM) SAM 2nd-bwd scratch
450	         + mb_tc_muon_floats(nCTA)                      // STAGED-opt (Muon) NS per-matrix scratch
451	#if SG_MB_TC_PROFILE
452	         + (int64_t)nCTA * SG_MBTC_PROF_SLOTS * 2 + 2  // phase-profiler (doubles=2 floats) + align pad
453	#endif
454	         ;
455	}
456	
457	template <OptId Opt>
458	__global__ void SG_MBTC_LAUNCH_BOUNDS
459	fused_mamba_megakernel_tc(PersistentContext ctx,
460	                          float* __restrict__ params,
461	                          MambaTokenCtx tok,
462	                          float* __restrict__ grad,
463	                          float lr, int step, FusedOptState st) {
464	    __shared__ MbTcSmem sm;
465	    GridBarrier bar = ctx.barrier();
466	    const int cta = blockIdx.x;
467	    const int nCTA = (int)ctx.n_ctas;
468	    const int B = tok.B;
469	    const int T = B * mb::kSeq;
470	
471	    // Workspace partition.
472	    float* ws = tok.workspace;
473	    const int64_t acts_f = mb_tc_acts_floats(T);
474	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
475	    float* scratch_base = ws + acts_f;
476	    const int64_t scratch_per = mbtc::mb_tile_scratch_floats();
477	    float* part_base = scratch_base + (int64_t)nCTA * scratch_per;
478	    float* loss_part = part_base + (int64_t)nCTA * mbtc::kPartElems;
479	    float* loss_out  = loss_part + nCTA;
480	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
481	    // loss slot (matches mb_tc_workspace_floats's term order). G==1 → dw_part unused.
482	    float* dw_part   = loss_out + 1;
483	    const int kDwG   = mbtc::kMbDwSplitK;
484	    // STAGED-opt (Prodigy P2.6) cross-CTA reduce slots: [r slots | s slots | reduced d]
485	    // = 2*nCTA+1, carved AFTER the split-K dW partials (matches mb_tc_workspace_floats's
486	    // term order). Unused by every non-Prodigy tail (their P3 never touches it), so this
487	    // pointer derivation leaves those cells byte-identical.
488	    float* opt_reduce = dw_part + mb_tc_dw_part_floats();
489	    // LookSAM SAM 2nd-backward scratch, carved AFTER the Prodigy reduce slots (mamba has
490	    // NO Muon region — unlike the decoder/vit twins — so this follows opt_reduce; term
491	    // order matches mb_tc_workspace_floats). Carving it here keeps every prior region's
492	    // offset unchanged, so the already-green cells are byte-identical. Layout:
493	    //   [sam_backup (total)] [sam_grad (total)]. Unused unless Opt==LookSAM.
494	    float* sam_backup = opt_reduce + mb_tc_opt_reduce_floats(nCTA);
495	    float* sam_grad   = sam_backup + kMambaTotalElems;
496	    // Muon NS per-matrix scratch, carved AFTER the LookSAM sam scratch (term order matches
497	    // mb_tc_workspace_floats — carving it LAST [before the optional profiler] keeps every
498	    // prior region's offset unchanged, so the already-green mamba cells are byte-identical).
499	    // Unused unless Opt==Muon. Layout (mirrors the decoder/vit twins):
500	    //   [muon_X | muon_AX | muon_AAX | muon_orth] (each kMbMuonMaxNumel)
501	    //   [muon_A (kMbMuonMaxRows²)] [nrm_partials (nCTA)] [inv_norm (1)]
502	    float* muon_base  = sam_grad + kMambaTotalElems;
503	#if SG_MB_TC_PROFILE
504	    // 8-byte align the double accumulator: round the float offset up to an even
505	    // count so reinterpret_cast<double*> is aligned (past the Muon NS scratch — the
506	    // phase-profiler is the LAST workspace term, mirroring mb_tc_workspace_floats).
507	    float* prof_f = muon_base + mb_tc_muon_floats(nCTA);
508	    uintptr_t _pa = reinterpret_cast<uintptr_t>(prof_f);
509	    if (_pa & 0x7u) prof_f = reinterpret_cast<float*>((_pa + 7u) & ~uintptr_t(7u));
510	    double* prof = reinterpret_cast<double*>(prof_f);   // [nCTA*SLOTS], host-zeroed
511	    long long _pt = 0;
512	#endif
513	
514	    mbtc::MbActs acts = mbtc::mb_acts_bind(acts_base, T);
515	    mbtc::MbTileScratch sc = mbtc::mb_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
516	    float* my_part = part_base + (int64_t)cta * mbtc::kPartElems;
517	    mbtc::MbPartial part = mbtc::mb_partial_bind(my_part);
518	
519	    MambaWeights w = mb_bind(params);
520	
521	    // ── P0: zero this CTA's non-GEMM grad partial + loss slot. ──
522	    for (int64_t i = threadIdx.x; i < mbtc::kPartElems; i += blockDim.x) my_part[i] = 0.0f;
523	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
524	    bar.sync();   // B0
525	
526	    // ── P1: sample-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
527	    //    kTileM rows; fwd (→ acts X, NLL) then bwd (→ acts dY, dh0, partial). ──
528	    const int nrows_tile = mbtc::kTileM;
529	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
530	    float nll_acc = 0.0f;
531	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
532	        const int g0 = ti * nrows_tile;
533	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
534	        SG_MBTC_PROF_TIC(_pt);
535	        float nll = mbtc::mbtc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
536	                                            sm.sA, sm.sB, sm.red);
537	        SG_MBTC_PROF_ACC(0, _pt);
538	        SG_MBTC_PROF_TIC(_pt);
539	        mbtc::mbtc_backward_tile(w, g0, nrows, B, acts, sc, part, tok.tokens, tok.targets,
540	                                 sm.sA, sm.sB, sm.red, sm.dBmat, sm.dCmat);
541	        SG_MBTC_PROF_ACC(1, _pt);
542	        if (threadIdx.x == 0) nll_acc += nll;
543	        __syncthreads();
544	    }
545	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
546	    bar.sync();   // B1: all acts (X + dY + dh0) + partials complete
547	    SG_MBTC_PROF_TIC(_pt);
548	
549	    // ── P2: assemble all 28 grads. 8 projection dW output-stationary (gt %
550	    //    nCTA), dt_proj.bias, non-GEMM partial-reduce, embedding owner-scan. ──
551	    if (threadIdx.x == 0) mbtc::mbtc_build_dw_specs(acts, T, sm.spec);
552	    __syncthreads();
553	    mbtc::MbDwSpec* spec = sm.spec;
554	    const int n_dw = mbtc::mbtc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
555	    SG_MBTC_PROF_TIC(_pt);
556	#if !SG_MBTC_BYPASS_DW_GEMM
557	    if (kDwG > 1) {
558	        // SPLIT-K (multi-CTA tiling): fan (n_dw·G) (tile,chunk) partials over the
559	        // grid so the ~73% idle SMs do work; deterministic ascending-chunk reduce.
560	        for (int item = cta; item < n_dw * kDwG; item += nCTA) {
561	            const int gt = item / kDwG, kc = item % kDwG;
562	            mbtc::mbtc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
563	        }
564	        bar.sync();   // all (gt,kc) partials complete before the reduce reads them
565	        mbtc::mbtc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec, n_dw, kDwG, dw_part, grad, cta, nCTA);
566	    } else {
567	        for (int gt = cta; gt < n_dw; gt += nCTA)
568	            mbtc::mbtc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, grad, sm.sA, sm.sB);
569	    }
570	#else
571	    (void)n_dw; (void)dw_part; (void)kDwG;
572	#endif
573	    SG_MBTC_PROF_ACC(4, _pt);          // P2-a: projection dW GEMMs (K=T)
574	    SG_MBTC_PROF_TIC(_pt);
575	    mbtc::mbtc_dw_biases(spec, grad, cta, nCTA);
576	    mbtc::mbtc_partial_reduce(part_base, grad, nCTA, cta);
577	    SG_MBTC_PROF_ACC(5, _pt);          // P2-b: biases + non-GEMM partial reduce
578	    SG_MBTC_PROF_TIC(_pt);
579	#if !SG_MBTC_BYPASS_EMBED_SCAN
580	    mbtc::mbtc_embed_owner_scan(acts, tok.tokens, T, grad, cta, nCTA);
581	#endif
582	    SG_MBTC_PROF_ACC(6, _pt);          // P2-c: embedding owner-scan (O(vocab·T))
583	    // Loss reduce (fp64 ordered) by CTA 0.
584	    if (cta == 0 && threadIdx.x == 0) {
585	        double s = 0.0;
586	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
587	        *tok.loss_out = (float)(s / (double)B);
588	    }
589	    (void)loss_out;
590	    SG_MBTC_PROF_ACC(2, _pt);          // close P2 (dW GEMM + reduce + embed + loss)
591	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
592	    SG_MBTC_PROF_TIC(_pt);             // open P3 (optimizer tail)
593	
594	    // ── P2.4 (LookSAM ONLY, SAM steps): the MODEL-COUPLED SAM 2nd backward that
595	    //    produces st.sam_dir = g_sam − g (INTEGRATION-OPTSTAGES §6). PORT of the
596	    //    decoder twin's P2.4 (fused_decoder_megakernel.cuh) onto the Mamba tile fns.
597	    //    ⚠ LANDED-DORMANT / NOT PRODUCTION-ROUTED: mamba×looksam is BLOCKED on the SAME
598	    //    PRE-EXISTING shared mamba scan/forward A/A/A race that blocks mamba×prodigy (this
599	    //    port is faithful; the failure is NOT in this code — it shows EVEN on a SAM-OFF
600	    //    step). dispatch.cpp's mb_looksam carve-out (env SG_MAMBA_LOOKSAM_PROBE to lift) +
601	    //    the Python registries keep this branch unreachable from the race until the shared
602	    //    mamba forward (megakernel_common.cuh GridBarrier / model_stage_mamba3.cuh) is fixed
603	    //    by its owner. Kept here (if-constexpr'd, proven byte-identical for every non-LookSAM
604	    //    Opt — mamba×{adamw,lion,grokfast} stay bit-identical A/A/A) as the ready start point
605	    //    for that fix. decoder/vit looksam ARE A/A/A-clean + registered-converted.

605	    //    for that fix. decoder/vit looksam ARE A/A/A-clean + registered-converted.
606	    //    Eager LookSAM, every k steps (looksam.py sam_step + looksam.h):
607	    //      ‖g‖     = GLOBAL L2 norm over ALL reduced grads; rho_over_norm = rho/‖g‖
608	    //      p'      = p + rho_over_norm·g          (perturb in the grad direction;
609	    //                backup = p.clone() for the exact restore — fp32 add is not
610	    //                bit-reversible, so we MUST save, not subtract back)
611	    //      g_sam   = ∇L(p')                       (a FULL SECOND in-kernel fwd+bwd +
612	    //                deterministic grad assembly at the perturbed weights, written to
613	    //                the SEPARATE `sam_grad` buffer so `grad` (the first grad the apply
614	    //                tail blends from) is untouched)
615	    //      sam_dir = g_sam − g                    (cached in the PERSISTENT `extra`
616	    //                state slice == st.sam_dir; reused verbatim on the k−1 intervening
617	    //                steps where looksam_sam==0, so NO 2nd pass runs then)
618	    //      restore p = backup
619	    //    The apply tail (P3, apply_optimizer<LookSAM>) then blends g_adj=(1−α)g+α·
620	    //    sam_dir and runs AdamW — UNCHANGED. DETERMINISM: the ‖g‖ reduction is the
621	    //    IDENTICAL deterministic ascending-CTA shape as GrokAdamW's P2.5 (fixed
622	    //    contiguous per-CTA range → per-CTA partial → CTA0 ascending sum), and the 2nd
623	    //    fwd+bwd+assembly reuses the SAME machinery as the first pass (fixed tile
624	    //    ownership, the deterministic ascending-CTA partial-reduce), so the whole phase
625	    //    is deterministic to the SAME degree as the first pass. Guarded so every other
626	    //    opt's path is byte-identical (no extra barrier / work). On a NON-SAM step
627	    //    (looksam_sam==0) this whole block is skipped — st.sam_dir already holds the
628	    //    cached direction.
629	    if constexpr (Opt == OptId::LookSAM) {
630	        if (st.looksam_sam != 0.0f) {
631	            // (a) GLOBAL ‖g‖ over the reduced grad, deterministic (reuse the loss
632	            //     workspace as P2.5 does: loss_part[nCTA] = per-CTA Σg², loss_out[1]
633	            //     broadcasts rho_over_norm). The reduced loss is already in
634	            //     *tok.loss_out (host state), so this is free scratch.
635	            float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
636	            float* ron_bc  = loss_out;           // [1] broadcast rho_over_norm
637	            const int64_t total_e = kMambaTotalElems;
638	            {
639	                const int64_t base = total_e / nCTA, rem = total_e % nCTA;
640	                const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
641	                const int64_t ecnt = base + (cta < rem ? 1 : 0);
642	                float tsum = 0.0f;
643	                for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
644	                    const float gv = grad[e0 + i];
645	                    tsum += gv * gv;
646	                }
647	                float* red = sm.red;
648	                red[threadIdx.x] = tsum;
649	                __syncthreads();
650	                for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
651	                    if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
652	                    __syncthreads();
653	                }
654	                if (threadIdx.x == 0) sq_part[cta] = red[0];
655	                bar.sync();   // B2.4a: all per-CTA Σg² partials complete
656	                if (cta == 0 && threadIdx.x == 0) {
657	                    double ss = 0.0;
658	                    for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
659	                    const float gnorm = sqrtf((float)ss);
660	                    // rho / ‖g‖ (matches bindings.cpp looksam_perturb_all). gnorm>0 in
661	                    // any real training step; guard div-by-0 → 0 (no perturb) to be safe.
662	                    *ron_bc = (gnorm > 0.0f) ? (st.rho / gnorm) : 0.0f;
663	                }
664	                bar.sync();   // B2.4b: rho_over_norm broadcast ready
665	            }
666	            const float rho_over_norm = *ron_bc;
667	            // (b) Backup + perturb p in place: p' = p + rho_over_norm·g. Grid-strided
668	            //     over the flat param vector (each element owned once → no race).
669	            {
670	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
671	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
672	                     i < total_e; i += gstride) {
673	                    sam_backup[i] = params[i];
674	                    params[i] = params[i] + rho_over_norm * grad[i];
675	                }
676	            }
677	            bar.sync();   // B2.4c: all params perturbed before the 2nd forward reads them
678	            // (c) SECOND fwd+bwd at the perturbed weights → g_sam in `sam_grad`. Mirror
679	            //     P1 + P2 EXACTLY, but: re-zero the per-CTA non-GEMM partial (it
680	            //     accumulates), do NOT write the loss (keep the first-pass loss), and
681	            //     assemble into `sam_grad` (NOT `grad`). `w` wraps `params` (now
682	            //     perturbed) so the tile fns read the perturbed weights with no re-bind.
683	            for (int64_t i = threadIdx.x; i < mbtc::kPartElems; i += blockDim.x) my_part[i] = 0.0f;
684	            bar.sync();   // B2.4d: partials cleared before the 2nd backward accumulates
685	            for (int ti = cta; ti < n_tiles; ti += nCTA) {
686	                const int g0 = ti * nrows_tile;
687	                const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
688	                mbtc::mbtc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
689	                                        sm.sA, sm.sB, sm.red);
690	                mbtc::mbtc_backward_tile(w, g0, nrows, B, acts, sc, part, tok.tokens, tok.targets,
691	                                         sm.sA, sm.sB, sm.red, sm.dBmat, sm.dCmat);
692	                __syncthreads();
693	            }
694	            bar.sync();   // B2.4e: all 2nd-pass acts (X + dY + dh0) + partials complete
695	            // Re-build the dW specs from the 2nd-pass acts (dY adjoints changed).
696	            if (threadIdx.x == 0) mbtc::mbtc_build_dw_specs(acts, T, sm.spec);
697	            __syncthreads();
698	            mbtc::MbDwSpec* spec2 = sm.spec;
699	            const int n_dw2 = mbtc::mbtc_dw_total_tiles<SG_TUNED_TILE_N>(spec2);
700	            if (kDwG > 1) {
701	                for (int item = cta; item < n_dw2 * kDwG; item += nCTA) {
702	                    const int gt = item / kDwG, kc = item % kDwG;
703	                    mbtc::mbtc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec2, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
704	                }
705	                bar.sync();
706	                mbtc::mbtc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec2, n_dw2, kDwG, dw_part, sam_grad, cta, nCTA);
707	            } else {
708	                for (int gt = cta; gt < n_dw2; gt += nCTA)
709	                    mbtc::mbtc_dw_run_tile<SG_TUNED_TILE_N>(spec2, gt, sam_grad, sm.sA, sm.sB);
710	            }
711	            mbtc::mbtc_dw_biases(spec2, sam_grad, cta, nCTA);
712	            mbtc::mbtc_partial_reduce(part_base, sam_grad, nCTA, cta);
