1020	template <OptId Opt>
1021	cudaError_t launch_fused_mamba_megakernel_tc(
1022	        PersistentContext ctx, float* params, MambaTokenCtx tok,
1023	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
1024	        int ncta_cap = 0) {
1025	    int dev = 0;
1026	    cudaError_t err = cudaGetDevice(&dev);
1027	    if (err != cudaSuccess) return err;
1028	    int n_sms = 0;
1029	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1030	    if (err != cudaSuccess) return err;
1031	
1032	    int occ = 0;
1033	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1034	        &occ, (const void*)&fused_mamba_megakernel_tc<Opt>, SG_MB_TC_MEGA_BLOCK,
1035	        /*dynamicSMemBytes=*/0);
1036	    if (err != cudaSuccess) return err;
1037	    if (occ < 1) return cudaErrorLaunchOutOfResources;
1038	
1039	    // OCCUPANCY-FILL: at min-blocks≥2 the kernel is built ≤128 reg/thread so `occ`
1040	    // CTAs co-reside per SM. Launch occ·n_sms CTAs (one full residency set) so the
1041	    // co-resident CTAs hide each other's HBM latency across the scan/conv/LN phases
1042	    // that run fully exposed at occ=1 — the persistent grid barrier rendezvous is
1043	    // over the LAUNCHED count and occ·n_sms are guaranteed simultaneously resident,
1044	    // so it stays hang-free. Determinism is per fixed launched nCTA (ascending-CTA
1045	    // reduce). At min-blocks==1 (shipped default) occ==1 → identical to before.
1046	    unsigned waves = (SG_MBTC_MIN_BLOCKS_PER_SM >= 2 && occ > 1) ? (unsigned)occ : 1u;
1047	    unsigned launch_ctas = (unsigned)n_sms * waves;
1048	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
1049	    ctx.n_ctas = launch_ctas;
1050	    // B%16: the dW K-loop contracts K=T=B·8 in 16-step atoms. It ALSO guarantees
1051	    // FULL tiles (T%kTileM==0 for kTileM∈{64,128}), which the projection GEMMs
1052	    // REQUIRE — they process a compile-time M-extent of kTileM rows (kAtomsM
1053	    // atoms), NOT the runtime `nrows`; a partial final tile would feed garbage
1054	    // pad rows to the wgmma while the scalar scan/conv loops process only nsamp.
1055	    // (A future relaxation to B%2 would satisfy the K-atom reason but silently
1056	    // break partial tiles — keep B%16.)
1057	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
1058	    // SPLIT-K dW (G>1) needs equal 16-aligned K-chunks: G must divide k_steps_total
1059	    // = T/16 = B·kSeq/16 = B/2 (kSeq=8). With B%16==0, B/2%4==0, so G∈{1,2,4} are
1060	    // always legal; a larger/odd G that doesn't divide B/2 would silently DROP the
1061	    // remainder k-steps from every dW (a correctness bug) — REFUSE loudly instead.
1062	    if (mbtc::kMbDwSplitK > 1 && (((int64_t)tok.B * mb::kSeq / wgs::kWgmmaAtomK) % mbtc::kMbDwSplitK) != 0)
1063	        return cudaErrorInvalidValue;
1064	
1065	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
1066	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
1067	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
1068	
1069	    dim3 grid(launch_ctas), block(SG_MB_TC_MEGA_BLOCK);
1070	    fused_mamba_megakernel_tc<Opt><<<grid, block, 0, stream>>>(
1071	        ctx, params, tok, grad, lr, step, st);
1072	    return cudaGetLastError();
1073	}
